@replay : ∀ {σ : Type u_2} (j : σ) (d e : σ →₀ ℕ),
  hasseCoeff d (e + Finsupp.single j 1 + d) * (e j + 1) =
    (d j + 1) * hasseCoeff (d + Finsupp.single j 1) (e + Finsupp.single j 1 + d)

@replay : ∀ {σ : Type u_3} {R : Type u_4} [inst : CommSemiring R] {d a : σ →₀ ℕ},
  (∀ j ∈ d.support, a j = 0) →
    ∀ (c : R) (g : MvPolynomial σ R), (hasseDeriv d) ((monomial a) c * g) = (monomial a) c * (hasseDeriv d) g

@Polynomial.hasseDeriv_mul : ∀ {R : Type u_3} [inst : Semiring R] (k : ℕ) (f g : Polynomial R),
  (Polynomial.hasseDeriv k) (f * g) =
    ∑ ij ∈ Finset.antidiagonal k, (Polynomial.hasseDeriv ij.1) f * (Polynomial.hasseDeriv ij.2) g

@LinearMap.map_smul : ∀ {R : Type u_3} {M : Type u_4} {M₂ : Type u_5} [inst : Semiring R] [inst_1 : AddCommMonoid M]
  [inst_2 : AddCommMonoid M₂] [inst_3 : Module R M] [inst_4 : Module R M₂] (fₗ : M →ₗ[R] M₂) (c : R) (x : M),
  fₗ (c • x) = c • fₗ x

@hasseDeriv_single_aeval_X : ∀ {σ : Type u_3} {R : Type u_4} [inst : CommSemiring R] (j : σ) (n : ℕ) (f : Polynomial R),
  (hasseDeriv (Finsupp.single j n)) ((Polynomial.aeval (X j)) f) =
    (Polynomial.aeval (X j)) ((Polynomial.hasseDeriv n) f)

@Polynomial.lhom_ext' : ∀ {R : Type u_1} [inst : Semiring R] {M : Type u_2} [inst_1 : AddCommMonoid M]
  [inst_2 : Module R M] {f g : Polynomial R →ₗ[R] M},
  (∀ (n : ℕ), f ∘ₗ Polynomial.monomial n = g ∘ₗ Polynomial.monomial n) → f = g

@Polynomial.aeval_monomial : ∀ {R : Type u_1} {A : Type u_2} [inst : CommSemiring R] [inst_1 : Semiring A]
  [inst_2 : Algebra R A] (x : A) {n : ℕ} {r : R},
  (Polynomial.aeval x) ((Polynomial.monomial n) r) = (algebraMap R A) r * x ^ n

@uniqueAlgEquiv_hasseDeriv : ∀ {σ : Type u_3} {R : Type u_4} [inst : CommSemiring R] [inst_1 : Unique σ] (n : ℕ)
  (P : MvPolynomial σ R),
  (uniqueAlgEquiv R σ) ((hasseDeriv (Finsupp.single default n)) P) = (Polynomial.hasseDeriv n) ((uniqueAlgEquiv R σ) P)

@Polynomial.lhom_ext' : ∀ {R : Type u_3} [inst : Semiring R] {M : Type u_4} [inst_1 : AddCommMonoid M]
  [inst_2 : Module R M] {f g : Polynomial R →ₗ[R] M},
  (∀ (n : ℕ), f ∘ₗ Polynomial.monomial n = g ∘ₗ Polynomial.monomial n) → f = g

@LinearEquiv.conj_apply_apply : ∀ {R₁' : Type u_1} {R₂' : Type u_2} {M₁' : Type u_3} {M₂' : Type u_4}
  [inst : CommSemiring R₁'] [inst_1 : CommSemiring R₂'] [inst_2 : AddCommMonoid M₁'] [inst_3 : AddCommMonoid M₂']
  [inst_4 : Module R₁' M₁'] [inst_5 : Module R₂' M₂'] {σ₁'₂' : R₁' →+* R₂'} {σ₂'₁' : R₂' →+* R₁'}
  [inst_6 : RingHomInvPair σ₁'₂' σ₂'₁'] [inst_7 : RingHomInvPair σ₂'₁' σ₁'₂'] (e : M₁' ≃ₛₗ[σ₁'₂'] M₂')
  (f : Module.End R₁' M₁') (x : M₂'), (e.conj f) x = e (f (e.symm x))

@Finsupp.card_Iic : ∀ {ι : Type u_2} {α : Type u_3} [inst : AddCommMonoid α] [inst_1 : PartialOrder α]
  [inst_2 : IsBotZeroClass α] [inst_3 : OrderBot α] [inst_4 : LocallyFiniteOrder α] [inst_5 : DecidableEq ι]
  [inst_6 : DecidableEq α] (f : ι →₀ α), (Finset.Iic f).card = ∏ i ∈ f.support, (Finset.Iic (f i)).card

def BoxIntervalChecks.no_decidable_eq.{u_2} : {τ : Type u_2} → [Fintype τ] → (τ → ℕ) → Finset (τ →₀ ℕ) :=
fun {τ} [Fintype τ] r ↦
  Finset.map Finsupp.equivFunOnFinite.symm.toEmbedding (Fintype.piFinset fun j ↦ Finset.range (r j + 1))

@Finsupp.weight : {σ : Type u_2} →
  {M : Type u_3} →
    {R : Type u_4} → [inst : Semiring R] → (σ → M) → [inst_1 : AddCommMonoid M] → [Module R M] → (σ →₀ R) →+ M

@Finsupp.weight_eq_sum : ∀ {σ : Type u_2} {M : Type u_3} {R : Type u_4} [inst : Semiring R] (w : σ → M)
  [inst_1 : AddCommMonoid M] [inst_2 : Module R M] [inst_3 : Fintype σ] (f : σ →₀ R),
  (Finsupp.weight w) f = ∑ i, f i • w i

@Finsupp.weight_eq_zero_iff_eq_zero : ∀ {σ : Type u_2} {M : Type u_3} [inst : AddCommMonoid M] [inst_1 : PartialOrder M]
  [IsOrderedAddMonoid M] [CanonicallyOrderedAdd M] (w : σ → M) [Finsupp.NonTorsionWeight ℕ w] {f : σ →₀ ℕ},
  (Finsupp.weight w) f = 0 ↔ f = 0

@Finsupp.linearCombination_mapDomain : ∀ {α : Type u_3} (R : Type u_4) [inst : Semiring R] {α' : Type u_5}
  {M' : Type u_6} [inst_1 : AddCommMonoid M'] [inst_2 : Module R M'] {v' : α' → M'} (f : α → α') (l : α →₀ R),
  (Finsupp.linearCombination R v') (Finsupp.mapDomain f l) = (Finsupp.linearCombination R (v' ∘ f)) l

@AlternatingMap.map_linearDependent : ∀ {ι : Type u_1} {K : Type u_2} {M : Type u_3} {N : Type u_4} [inst : Ring K]
  [IsDomain K] [inst_2 : AddCommGroup M] [inst_3 : Module K M] [inst_4 : AddCommGroup N] [inst_5 : Module K N]
  [Module.IsTorsionFree K N] (f : M [⋀^ι]→ₗ[K] N) (v : ι → M), ¬LinearIndependent K v → f v = 0

@Matrix.det_eq_zero_of_not_linearIndependent_cols : ∀ {m : Type u_2} [inst : DecidableEq m] [inst_1 : Fintype m]
  {R : Type u_1} [inst_2 : CommRing R] [IsDomain R] {A : Matrix m m R},
  (¬LinearIndependent R fun i ↦ A.transpose i) → A.det = 0

@Roth.coeff_wronskian_of_natDegree_injective : ∀ {K : Type u_1} [inst : Field K] {l : ℕ} {φ : Fin l → K[X]},
  (Roth.wronskian φ).coeff (∑ ν, (φ ν).natDegree - ∑ ν, ↑ν) =
    (∏ ν, (φ ν).leadingCoeff) * (Matrix.of fun μ ν ↦ ↑((φ ν).natDegree.choose ↑μ)).det

theorem MvPolynomial.algHom_C.{u, u_1, u_2} : ∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {A : Type u_2}
  [inst_1 : Semiring A] [inst_2 : Algebra R A] (f : MvPolynomial σ R →ₐ[R] A) (r : R), f (C r) = (algebraMap R A) r :=
fun {R} {σ} [CommSemiring R] {A} [Semiring A] [Algebra R A] f r ↦ AlgHom.commutes f r

@aeval_monomial : ∀ {R : Type u_1} {S₁ : Type u_2} {σ : Type u_3} [inst : CommSemiring R] [inst_1 : CommSemiring S₁]
  [inst_2 : Algebra R S₁] (g : σ → S₁) (d : σ →₀ ℕ) (r : R),
  (aeval g) ((monomial d) r) = (algebraMap R S₁) r * d.prod fun i k ↦ g i ^ k

@replay : ∀ {σ : Type u_3} {R : Type u_4} [inst : CommSemiring R] (i : σ) (f : R[X]) (B : MvPolynomial σ R),
  (∀ e ∈ B.support, e i = 0) →
    ∀ (d : σ →₀ ℕ), ((Polynomial.aeval (X i)) f * B).coeff d = f.coeff (d i) * B.coeff (Finsupp.erase i d)

@comp_aeval : ∀ {R : Type u_3} {S₁ : Type u_4} {σ : Type u_5} [inst : CommSemiring R] [inst_1 : CommSemiring S₁]
  [inst_2 : Algebra R S₁] (f : σ → S₁) {B : Type u_6} [inst_3 : CommSemiring B] [inst_4 : Algebra R B] (φ : S₁ →ₐ[R] B),
  φ.comp (aeval f) = aeval fun i ↦ φ (f i)

@comp_aeval_apply : ∀ {R : Type u_3} {S₁ : Type u_4} {σ : Type u_5} [inst : CommSemiring R] [inst_1 : CommSemiring S₁]
  [inst_2 : Algebra R S₁] (f : σ → S₁) {B : Type u_6} [inst_3 : CommSemiring B] [inst_4 : Algebra R B] (φ : S₁ →ₐ[R] B)
  (p : MvPolynomial σ R), φ ((aeval f) p) = (aeval fun i ↦ φ (f i)) p

@MvPolynomial.taylor_map : ∀ {σ : Type u_1} {R : Type u_2} [inst : CommSemiring R] {S : Type u_3}
  [inst_1 : CommSemiring S] (f : R →+* S) (α : σ → R) (P : MvPolynomial σ R),
  (MvPolynomial.taylor fun j ↦ f (α j)) ((MvPolynomial.map f) P) = (MvPolynomial.map f) ((MvPolynomial.taylor α) P)

@MvPolynomial.taylor_rename : ∀ {σ : Type u_1} {R : Type u_2} [inst : CommSemiring R] {τ : Type u_3} (f : σ → τ)
  (α : τ → R) (P : MvPolynomial σ R),
  (MvPolynomial.taylor α) ((MvPolynomial.rename f) P) = (MvPolynomial.rename f) ((MvPolynomial.taylor (α ∘ f)) P)

@MvPolynomial.aeval_rename : ∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} {S : Type u_4} [inst : CommSemiring R]
  [inst_1 : CommSemiring S] (k : σ → τ) (g : τ → S) (p : MvPolynomial σ R) [inst_2 : Algebra R S],
  (MvPolynomial.aeval g) ((MvPolynomial.rename k) p) = (MvPolynomial.aeval (g ∘ k)) p

@MvPolynomial.aeval_comp_rename : ∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} {S : Type u_4} [inst : CommSemiring R]
  [inst_1 : CommSemiring S] (k : σ → τ) (g : τ → S) [inst_2 : Algebra R S],
  (MvPolynomial.aeval g).comp (MvPolynomial.rename k) = MvPolynomial.aeval (g ∘ k)

@degreeOf_eq_natDegree : ∀ {R : Type u_3} {σ : Type u_4} [inst : CommSemiring R] [inst_1 : DecidableEq σ] (a : σ)
  (p : MvPolynomial σ R),
  degreeOf a p = ((optionEquivLeft R { b // b ≠ a }) ((rename ⇑(Equiv.optionSubtypeNe a).symm) p)).natDegree

@injective_iff_map_eq_zero' : ∀ {F : Type u_3} {G : Type u_4} {H : Type u_5} [inst : AddGroup G]
  [inst_1 : AddZeroClass H] [inst_2 : FunLike F G H] [AddMonoidHomClass F G H] (f : F),
  Function.Injective ⇑f ↔ ∀ (a : G), f a = 0 ↔ a = 0

@withoutDecidableEq : ∀ {σ : Type u_3} {A : Type u_4} [inst : CommRing A] [inst_1 : Fintype σ] (α : σ → A) (r : σ → ℕ)
  (P : MvPolynomial σ A),
  (∀ (j : σ), degreeOf j P ≤ r j) → P = ∑ d ∈ Roth.box r, C ((eval α) ((hasseDeriv d) P)) * ∏ j, (X j - C (α j)) ^ d j

@callerWithoutDecidableEq : ∀ {σ : Type u_3} {A : Type u_4} [inst : CommRing A] [inst_1 : Fintype σ] (α x : σ → A)
  (r : σ → ℕ) (P : MvPolynomial σ A),
  (∀ (j : σ), degreeOf j P ≤ r j) → (eval x) P = ∑ d ∈ Roth.box r, (eval α) ((hasseDeriv d) P) * ∏ j, (x j - α j) ^ d j

@withoutDecidableEq : ∀ {σ : Type u_3} {A : Type u_4} [inst : CommRing A] [inst_1 : Fintype σ] (α x : σ → A) (r : σ → ℕ)
  (P : MvPolynomial σ A),
  (∀ (j : σ), degreeOf j P ≤ r j) → (eval x) P = ∑ d ∈ Roth.box r, (eval α) ((hasseDeriv d) P) * ∏ j, (x j - α j) ^ d j

@evaluation : ∀ {σ : Type u_4} {R : Type u_5} {S : Type u_6} [inst : CommSemiring R] [inst_1 : CommSemiring S]
  [inst_2 : Algebra R S] (P : MvPolynomial σ R) (x : S),
  (Polynomial.aeval x) (DiagonalAssessment.generalized P) = (MvPolynomial.aeval fun x_1 ↦ x) P

@Finsupp.sum_of_support_subset : ∀ {α : Type u_2} {M : Type u_3} {N : Type u_4} [inst : Zero M]
  [inst_1 : AddCommMonoid N] (f : α →₀ M) {s : Finset α},
  f.support ⊆ s → ∀ (g : α → M → N), (∀ i ∈ s, g i 0 = 0) → f.sum g = ∑ x ∈ s, g x (f x)
